export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/t21c
rm -rf "$D"; mkdir -p "$D"; cd "$D" || exit 1
base64 -d > /tmp/t21c.zip <<'B64EOF'

B64EOF
unzip -oq /tmp/t21c.zip -d "$D"
for t in *.tcl; do
  b=${t%.tcl}
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source "$t" > "$b.log" 2>&1
  if grep -q "DONE_$b" "$b.log"; then echo "OK $b"; grep "^CHK" "$b.log"; else echo "FAIL $b"; grep -E "ERROR" "$b.log" | head -2; fi
done
tar czf /tmp/t21c.tgz *.bit 2>/dev/null; ls *.bit | wc -l; echo T21CDONE